SELECT DISTINCT promo_category || ' has ' || promo_cost AS costs
FROM promotions
ORDER BY 1;

SELECT DISTINCT promo_cost || ' in ' || DISTINCT promo_category
FROM promotions
ORDER BY 1;

SELECT promo_category, DISTINCT promo_cost
FROM promotions
ORDER BY 2;

SELECT promo_cost, promo_category
FROM promotions
ORDER BY 1;

